/* Dedicated service worker for web push reminders.
 * Registered with scope '/sw/' so it does not conflict with the main
 * workbox service worker (scope '/') generated by vite-plugin-pwa.
 */
self.addEventListener('install', () => {
	self.skipWaiting();
});

self.addEventListener('activate', (event) => {
	event.waitUntil(clients.claim());
});

self.addEventListener('push', (event) => {
	let title = '吾身 · 日记提醒';
	let body = '该写今天的日记啦 ✍️';
	let tag = 'diarum-reminder';

	if (event.data) {
		try {
			const data = event.data.json();
			if (data.title) title = data.title;
			if (data.body) body = data.body;
			if (data.tag) tag = data.tag;
		} catch (e) {
			// ignore malformed payload
		}
	}

	event.waitUntil(
		self.registration.showNotification(title, {
			body,
			tag,
			icon: '/favicon-192x192.png',
			badge: '/favicon-96x96.png',
			data: { url: '/' }
		})
	);
});

self.addEventListener('notificationclick', (event) => {
	event.notification.close();
	const url = (event.notification.data && event.notification.data.url) || '/';
	event.waitUntil(
		clients.matchAll({ type: 'window', includeUncontrolled: true }).then((windowClients) => {
			for (const client of windowClients) {
				if (client.url && client.url.indexOf('/') !== -1) {
					return client.navigate(url).then((c) => c && c.focus());
				}
			}
			return clients.openWindow(url);
		})
	);
});
